        --focus: Highlight;
        --error: Mark;
        --success: CanvasText;
      }

      .support-card,
      input,
      button,
      .skip-link {
        forced-color-adjust: auto;
      }

      button {
        border: 1px solid ButtonBorder;
        color: ButtonText;
        background: ButtonFace;
        box-shadow: none;
      }

      .status {
        border: 1px solid ButtonBorder;
      }
    }
  </style>
</head>
<body>
  <a class="skip-link" href="#main-content">Skip to main content</a>
  <div id="app"></div>

  <script>
    const state = {
      submitted: false
    };

    function createField({ id, label, type, required = false, autocomplete, helperText = '' }) {
      const labelText = required ? `${label} *` : label;
      const describedBy = [];
      if (helperText) describedBy.push(`${id}-help`);
      if (state.submitted) describedBy.push(`${id}-error`);

      return `
        <div class="form-field">
          <label for="${id}">${labelText}</label>
          <input
            id="${id}"
            name="${id}"
            type="${type}"
            ${required ? 'required aria-required="true"' : ''}
            ${autocomplete ? `autocomplete="${autocomplete}"` : ''}
            ${describedBy.length ? `aria-describedby="${describedBy.join(' ')}"` : ''}
          />
          ${helperText ? `<div class="field-help" id="${id}-help">${helperText}</div>` : ''}
          <div class="field-error" id="${id}-error" hidden aria-live="polite"></div>
        </div>
      `;
    }

    function App() {
      return `
        <main id="main-content" class="page-shell">
          <section class="support-card" aria-labelledby="support-title">
            <header class="support-card__header">
              <p class="eyebrow">Support</p>
              <h1 id="support-title">Contact our team</h1>
            </header>
            <div class="support-card__body">
              <p class="lead">Send a message and we’ll get back to you as soon as we can.</p>

              <form id="contact-form" novalidate>
                ${createField({
                  id: 'full-name',
                  label: 'Full name',
                  type: 'text',
                  required: true,
                  autocomplete: 'name'
                })}
                ${createField({
                  id: 'email-address',
                  label: 'Email address',
                  type: 'email',
                  required: true,
                  autocomplete: 'email'
                })}
                ${createField({
                  id: 'phone-number',
                  label: 'Phone number',
                  type: 'tel',
                  required: false,
                  autocomplete: 'tel',
                  helperText: 'Optional. Enter a number like +1 555 123 4567 or 555-123-4567.'
                })}

                <div class="actions">
                  <button type="submit">Send message</button>
                </div>

                <p class="status" id="success-message" hidden aria-live="polite" role="status">Your message is ready to send.</p>
              </form>
            </div>
            <footer>We only use your details to respond to your support request.</footer>
          </section>
        </main>
      `;
    }

    function setError(input, message) {
      const error = document.getElementById(`${input.id}-error`);
      input.setAttribute('aria-invalid', 'true');
      error.textContent = message;
      error.hidden = false;

      const help = document.getElementById(`${input.id}-help`);
      const describedBy = [help && help.id, error.id].filter(Boolean).join(' ');
      input.setAttribute('aria-describedby', describedBy);
    }

    function clearError(input) {
      const error = document.getElementById(`${input.id}-error`);
      input.removeAttribute('aria-invalid');
      error.textContent = '';
      error.hidden = true;

      const help = document.getElementById(`${input.id}-help`);
      if (help) {
        input.setAttribute('aria-describedby', help.id);
      } else {
        input.removeAttribute('aria-describedby');
      }
    }

    function validateForm(form) {
      const fields = {
        'full-name': form.elements['full-name'],
        'email-address': form.elements['email-address'],
        'phone-number': form.elements['phone-number']
      };

      let firstInvalid = null;

      clearError(fields['full-name']);
      clearError(fields['email-address']);
      clearError(fields['phone-number']);

      if (!fields['full-name'].value.trim()) {
        setError(fields['full-name'], 'Please enter your full name.');
        firstInvalid = firstInvalid || fields['full-name'];
      }

      if (!fields['email-address'].value.trim()) {
        setError(fields['email-address'], 'Please enter your email address.');
        firstInvalid = firstInvalid || fields['email-address'];
      } else if (!fields['email-address'].validity.valid) {
        setError(fields['email-address'], 'Please enter a valid email address.');
        firstInvalid = firstInvalid || fields['email-address'];
      }

      return firstInvalid;
    }

    function mount() {
      document.getElementById('app').innerHTML = App();

      const form = document.getElementById('contact-form');
      const successMessage = document.getElementById('success-message');

      form.addEventListener('submit', function (event) {
        event.preventDefault();
        state.submitted = true;
        successMessage.hidden = true;

        const firstInvalid = validateForm(form);

        if (firstInvalid) {
          firstInvalid.focus();
          return;
        }

        successMessage.hidden = false;
        successMessage.textContent = 'Thanks — your message is ready to send.';
        form.reset();

        Array.from(form.querySelectorAll('input')).forEach(clearError);
      });

      Array.from(form.querySelectorAll('input')).forEach(function (input) {
        input.addEventListener('input', function () {
          if (!state.submitted) return;
          validateForm(form);
        });
      });
    }

    mount();
  </script>
</body>
</html>
